    {
      "card_ids": ["C06"],
      "claim": "After oral administration of E. senticosus extract to rats, chlorogenic acid, rutin, and hyperoside were detected in brain, showing that glycosylated phenolic compounds can reach the CNS after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A phenylethanoid glycoside was detected in rat hippocampus and striatum after oral administration, supporting brain entry of polar glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Iridoid glycosides, including deacetyl asperulosidic acid methyl ester, were detected in rat brain microdialysates and tissue homogenates, confirming that glycosides can pass the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: the query is a luteolin C-glucoside, and multiple independent in vivo records show that glycosylated flavonoids and related polyphenol glycosides reach the brain after systemic administration, supporting meaningful CNS access.",
